mapper.update:
UPDATE SMT_AUTH_OPERATION_TARGET
SET STATE = 'QUEUED', UPDATE_TIME = #{updatedAt}
WHERE BATCH_ID = #{batchId} AND STATE = 'PREPARING'

UPDATE SMT_AUTH_OPERATION_TARGET
SET STATE = 'EXECUTING', LEASE_TOKEN = #{leaseToken},
	LEASE_UNTIL = #{leaseUntil}, UPDATE_TIME = #{now}
WHERE ID = #{targetId}
	AND STATE = #{expectedState}
	AND (LEASE_UNTIL IS NULL OR LEASE_UNTIL < #{now})

mapper.select:
SELECT * FROM (
	SELECT t.* FROM SMT_AUTH_OPERATION_TARGET t
	WHERE PARK_ID = #{parkId} AND OPERATION_QUEUE = #{operationQueue}
		AND ACCESS_TYPE = #{accessType} AND STATE = 'QUEUED'
		AND (NEXT_ATTEMPT_AT IS NULL OR NEXT_ATTEMPT_AT <= #{now})
		AND (LEASE_UNTIL IS NULL OR LEASE_UNTIL < #{now})


				AND ID IN #{id}

			AND 1 = 0

	ORDER BY ID
) WHERE ROWNUM <= #{maxCount}

mapper.update:
UPDATE SMT_AUTH_OPERATION_TARGET
SET STATE = 'WAITING_CONFIRM', DISPATCHED_AT = NVL(DISPATCHED_AT, #{updatedAt}),
	UPDATE_TIME = #{updatedAt}
WHERE ID = #{targetId} AND LEASE_TOKEN = #{leaseToken}
	AND STATE IN ('EXECUTING', 'WAITING_CONFIRM')
	AND (LEASE_UNTIL IS NULL OR LEASE_UNTIL > #{updatedAt})

mapper.select:
SELECT * FROM (
	SELECT ID, BATCH_ID, REQUEST_ID, PARK_ID, TARGET_KEY, SUBJECT_TYPE, SUBJECT_ID,
		SUBJECT_SNAPSHOT, RESOURCE_TYPE, DEVICE_ID, RESOURCE_ID, ACCESS_TYPE,
		OPERATION_QUEUE, ACTION, VALID_FROM, VALID_TO, OPERATION_VERSION,
		LEGACY_TASK_ID, STATE, RESULT_SUMMARY, FAILURE_REASON, ACCEPTED_AT,
		DISPATCHED_AT, CONFIRMED_AT, CONVERGED_AT, LEASE_TOKEN, LEASE_UNTIL,
		NEXT_ATTEMPT_AT, CREATE_TIME, UPDATE_TIME
	FROM SMT_AUTH_OPERATION_TARGET
	WHERE PARK_ID = #{parkId}
		AND STATE IN ('EXECUTING', 'WAITING_CONFIRM', 'VERIFYING')
		AND LEASE_UNTIL IS NOT NULL AND LEASE_UNTIL <= #{now}
	ORDER BY LEASE_UNTIL, ID
) WHERE ROWNUM <= #{maxCount}
